public void testTableBuilderFluentApiFromConnection() throws Exception {
    // Obtain a Connection and a TableBuilder for a table; the new API should expose getTableBuilder on Connection
    org.apache.hadoop.hbase.client.Connection conn = org.apache.hadoop.hbase.client.ConnectionFactory.createConnection();
    org.apache.hadoop.hbase.TableName tableName = org.apache.hadoop.hbase.TableName.valueOf("default", "test_table");

    // The refactored API is expected to provide a fluent TableBuilder from the Connection
    org.apache.hadoop.hbase.client.TableBuilder builder = conn.getTableBuilder(tableName);
    org.junit.Assert.assertNotNull("Connection#getTableBuilder should return a non-null TableBuilder", builder);

    // All setter methods on TableBuilder should be fluent and return the same builder instance
    org.junit.Assert.assertSame(builder, builder.setOperationTimeout(100));
    org.junit.Assert.assertSame(builder, builder.setRpcTimeout(200));
    org.junit.Assert.assertSame(builder, builder.setReadRpcTimeout(300));
    org.junit.Assert.assertSame(builder, builder.setWriteRpcTimeout(400));
    org.junit.Assert.assertSame(builder, builder.setWriteBufferSize(8192L));

    // Finally build() should return a non-null Table instance
    org.apache.hadoop.hbase.client.Table table = builder.build();
    org.junit.Assert.assertNotNull("TableBuilder#build should return a non-null Table", table);

    // Cleanup
    table.close();
    conn.close();
}

@Test
public void testResourceDecoratorDelegationAndSingleChildEnforcement() throws Exception {
    final byte[] data = "hello".getBytes("UTF-8");

    Resource resource1 = new Resource() {
        @Override public String getName() { return "r1"; }
        @Override public boolean isExists() { return true; }
        @Override public long getSize() { return data.length; }
        @Override public java.io.InputStream getInputStream() throws java.io.IOException { return new java.io.ByteArrayInputStream(data); }
    };

    // instantiate an anonymous subclass of the abstract ResourceDecorator
    ResourceDecorator decorator = new ResourceDecorator() { };

    ResourceCollection single = new ResourceCollection() {
        @Override public java.util.Iterator<Resource> iterator() { return java.util.Collections.<Resource>singleton(resource1).iterator(); }
        @Override public int size() { return 1; }
        @Override public boolean isFilesystemOnly() { return false; }
    };

    // configure decorator with a single resource
    decorator.addConfigured(single);

    // delegation assertions
    org.junit.Assert.assertEquals("r1", decorator.getName());
    org.junit.Assert.assertTrue(decorator.isExists());
    org.junit.Assert.assertEquals(data.length, decorator.getSize());

    byte[] buf = new byte[data.length];
    try (java.io.InputStream in = decorator.getInputStream()) {
        int read = in.read(buf);
        org.junit.Assert.assertEquals(data.length, read);
    }
    org.junit.Assert.assertArrayEquals(data, buf);

    // attempting to add a second resource collection must fail
    Resource resource2 = new Resource() {
        @Override public String getName() { return "r2"; }
    };
    ResourceCollection single2 = new ResourceCollection() {
        @Override public java.util.Iterator<Resource> iterator() { return java.util.Collections.<Resource>singleton(resource2).iterator(); }
        @Override public int size() { return 1; }
        @Override public boolean isFilesystemOnly() { return false; }
    };

    try {
        decorator.addConfigured(single2);
        org.junit.Assert.fail("Expected BuildException when adding a second resource");
    } catch (org.apache.tools.ant.BuildException expected) {
        // expected: decorator must reject a second child resource
    }
}
